def monitor_resource_state(resource, callback, exit_event=None):
    """Coroutine that monitors a KATCPResource's state.

    Calls callback(True/False) whenever the resource becomes connected or disconnected.
    Will always do an initial callback(False) call. Exits without calling callback() if
    exit_event is set
    """
    while True:
        if exit_event is not None and exit_event.is_set():
            return
        if resource.connected:
            callback(True)
        else:
            callback(False)
        yield from resource.wait_connected()


def monitor_resource_disconnected(resource, callback, exit_event=None):
    """Coroutine that monitors a KATCPResource's state.

    Calls callback() whenever the resource becomes disconnected. Will always do an
    initial callback() call. Exits without calling callback() if exit_event is set
    """
    while True:
        if exit_event is not None and exit_event.is_set():
            return
        if not resource.connected:
            callback()
        yield from resource.wait_connected()


